SELECT TO_CHAR(subquery.DATA, 'DD/MM/YYYY') AS DIA, subquery.CODNAT, (SELECT DESCRNAT FROM Natureza WHERE CODNAT = subquery.CODNAT) AS NOME_NATUREZA, SUM(subquery.RECEITAS) AS RECEITAS FROM ( SELECT FIN.DHBAIXA AS DATA, FIN.CODNAT, FIN.VLRBAIXA AS RECEITAS FROM TGFFIN FIN WHERE FIN.RECDESP = 1 AND FIN.DHBAIXA IS NOT NULL AND FIN.PROVISAO = 'N' AND TRUNC(FIN.DHBAIXA) >= TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15)) AND TRUNC(FIN.DHBAIXA) <= TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_FIM_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) + 15)) AND (:VAR_EMPRESA_FC IS NULL OR :VAR_EMPRESA_FC = '' OR INSTR(',' || :VAR_EMPRESA_FC || ',', ',' || FIN.CODEMP || ',') > 0) AND (:VAR_CONTA_BANCARIA_FC IS NULL OR :VAR_CONTA_BANCARIA_FC = '' OR INSTR(',' || :VAR_CONTA_BANCARIA_FC || ',', ',' || TO_CHAR(FIN.CODCTABCOINT) || ',') > 0) AND (:VAR_FILTRO_FC_NATUREZA_RECEITA IS NULL OR :VAR_FILTRO_FC_NATUREZA_RECEITA = '' OR INSTR(',' || :VAR_FILTRO_FC_NATUREZA_RECEITA || ',', ',' || FIN.CODNAT || ',') > 0) UNION ALL SELECT FIN.DTVENC AS DATA, FIN.CODNAT, FIN.VLRDESDOB AS RECEITAS FROM TGFFIN FIN WHERE FIN.RECDESP = 1 AND FIN.DHBAIXA IS NULL AND FIN.PROVISAO = 'N' AND FIN.DTVENC >= TRUNC(SYSDATE) AND TRUNC(FIN.DTVENC) >= TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15)) AND TRUNC(FIN.DTVENC) <= TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_FIM_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) + 15)) AND (:VAR_EMPRESA_FC IS NULL OR :VAR_EMPRESA_FC = '' OR INSTR(',' || :VAR_EMPRESA_FC || ',', ',' || FIN.CODEMP || ',') > 0) AND (:VAR_CONTA_BANCARIA_FC IS NULL OR :VAR_CONTA_BANCARIA_FC = '' OR INSTR(',' || :VAR_CONTA_BANCARIA_FC || ',', ',' || TO_CHAR(FIN.CODCTABCOINT) || ',') > 0) AND (:VAR_FILTRO_FC_NATUREZA_RECEITA IS NULL OR :VAR_FILTRO_FC_NATUREZA_RECEITA = '' OR INSTR(',' || :VAR_FILTRO_FC_NATUREZA_RECEITA || ',', ',' || FIN.CODNAT || ',') > 0) ) subquery GROUP BY TO_CHAR(subquery.DATA, 'DD/MM/YYYY'), subquery.CODNAT